            if b[x] != '.' and b[x] == b[y] and b[y] == b[z]:
                return b[x]
        if '.' not in b:
            return 'D'
        return '.'
    r = result(board)
    if r == 'D':
        return 0
    if r != '.':
        if r == player:
            return 1
        return -1
    other = 'O'
    if player == 'O':
        other = 'X'
    best = -2
    for i in range(9):
        if board[i] == '.':
            v = -negamax(board[:i] + player + board[i + 1:], other)
            if v > best:
                best = v
    return best

