def node_counts(board, player):
    lines = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]
    def result(b):
        for x, y, z in lines:
            if b[x] != '.' and b[x] == b[y] and b[y] == b[z]:
                return b[x]
        if '.' not in b:
            return 'D'
        return '.'
    def flip(p):
        if p == 'X':
            return 'O'
        return 'X'
    def plain(b, p):
        if result(b) != '.':
            return 1
        n = 1
        for i in range(9):
            if b[i] == '.':
                n += plain(b[:i] + p + b[i + 1:], flip(p))
        return n
    count = [0]
    def ab(b, p, alpha, beta):
        count[0] += 1
        r = result(b)
        if r == 'D':
            return 0
        if r != '.':
            if r == p:
                return 1
            return -1
        best = -2
        for i in range(9):
            if b[i] == '.':
                v = -ab(b[:i] + p + b[i + 1:], flip(p), -beta, -alpha)
                if v > best:
                    best = v
                if best > alpha:
                    alpha = best
                if alpha >= beta:
                    break
        return best
    ab(board, player, -2, 2)
    return [plain(board, player), count[0]]

