def symmetric_boards(board):
    def rot(b):
        out = ['.'] * 9
        for r in range(3):
            for c in range(3):
                out[c * 3 + (2 - r)] = b[r * 3 + c]
        return ''.join(out)
    def mirror(b):
        out = ['.'] * 9
        for r in range(3):
            for c in range(3):
                out[r * 3 + (2 - c)] = b[r * 3 + c]
        return ''.join(out)
    seen = []
    b = board
    for i in range(4):
        for x in (b, mirror(b)):
            if x not in seen:
                seen.append(x)
        b = rot(b)
    seen.sort()
    return seen

